<script setup lang="ts">
import { computed, ref } from 'vue'
import { api, post } from '../api'
import LegacyIcon from './LegacyIcon.vue'
import WorkspaceResourcePicker from './WorkspaceResourcePicker.vue'
import SystemWorkspaceSnapshot from './SystemWorkspaceSnapshot.vue'
interface Resources { skills: string[] | null; mcp: string[] | null; knowledge_bases: string[] | null }
interface Row { workspace_id: string; kind: 'system' | 'general' | 'workspace'; follows_root: boolean; display_name: string; path: string; archived: boolean; status: 'ready' | 'invalid'; error: string; instructions?: string; resources?: Resources }
const props = defineProps<{ row: Row; busy?: boolean; language?: string; run: (action: () => Promise<unknown>) => Promise<boolean> }>()
const tr = (zh: string, en: string) => props.language === 'en' ? en : zh
const editing = ref(false); const moving = ref(false); const instructionsOpen = ref(false); const resourcesOpen = ref(false)
const name = ref(props.row.display_name); const instructions = ref(props.row.instructions || ''); const destination = ref('')
const resources = ref<Resources>(props.row.resources ?? { skills: null, mcp: null, knowledge_bases: null })
const label = computed(() => props.row.kind === 'system' ? tr('系统工作区', 'System workspace') : props.row.kind === 'general' ? tr('默认工作区', 'Default workspace') : props.row.display_name)
async function save(body: Record<string, unknown>, close: 'edit' | 'instructions' | 'resources' | 'archive') {
  const saved = await props.run(() => api(`/api/settings/workspace/registrations/${encodeURIComponent(props.row.workspace_id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }))
  if (!saved) return
  if (close === 'edit') editing.value = false
  else if (close === 'instructions') instructionsOpen.value = false
  else if (close === 'resources') resourcesOpen.value = false
}
async function migrate() {
  if (!destination.value.trim()) return
  if (await props.run(() => post(`/api/settings/workspace/registrations/${encodeURIComponent(props.row.workspace_id)}/migrate`, { path: destination.value.trim() }))) moving.value = false
}
function editResources() { Object.assign(resources.value, props.row.resources ?? { skills: null, mcp: null, knowledge_bases: null }); resourcesOpen.value = !resourcesOpen.value }
</script>
<template><article class="workspace-row" :aria-label="label"><div class="workspace-row-heading"><LegacyIcon :name="row.kind === 'system' ? 'settings' : row.kind === 'general' ? 'network' : 'folder'" :size="18" /><h3>{{ label }}</h3><span v-if="row.archived" class="muted">{{ tr('已归档', 'Archived') }}</span><div class="workspace-row-actions"><RouterLink v-if="row.kind !== 'system' && !row.archived && row.status === 'ready'" :to="row.kind === 'general' ? '/chat?dt_workspace=' : `/chat?dt_workspace=${encodeURIComponent(row.workspace_id)}`"><LegacyIcon name="plus" :size="14" />{{ tr('新对话', 'New chat') }}</RouterLink><button v-if="row.kind !== 'system' && !row.archived" @click="editResources"><LegacyIcon name="settings" :size="14" />{{ tr('分配资源', 'Assign resources') }}</button><button v-if="row.kind !== 'system' && !row.archived" :aria-expanded="instructionsOpen" @click="instructions = row.instructions || ''; instructionsOpen = !instructionsOpen"><LegacyIcon name="document" :size="14" />{{ tr('工作区说明', 'Workspace instructions') }}</button><button v-if="row.kind === 'workspace'" :aria-label="tr('重命名工作区', 'Rename workspace')" @click="name = row.display_name; editing = !editing; moving = false"><LegacyIcon name="edit" :size="14" /></button><button :aria-label="tr('迁移目录', 'Move directory')" @click="moving = !moving; editing = false"><LegacyIcon name="folder" :size="14" /></button><button v-if="row.kind === 'workspace'" :aria-label="row.archived ? tr('恢复工作区', 'Restore workspace') : tr('归档工作区', 'Archive workspace')" @click="save({ archived: !row.archived }, 'archive')"><LegacyIcon name="archive" :size="14" /></button></div></div><div class="workspace-row-body"><p v-if="row.kind !== 'workspace'" class="muted">{{ row.kind === 'system' ? tr('仅保存脱敏配置快照、技能文件和 MCP 清单，API Key 与 Token 仍留在私有配置中。', 'Stores only redacted configuration snapshots, skill files, and MCP manifests. API keys and tokens remain in private settings.') : tr('未选择工作区的对话共享此目录中的文件。', 'Conversations without a selected workspace share files in this directory.') }}</p><code>{{ row.path }}</code><p v-if="row.archived" class="muted">{{ tr('已归档，现有会话与文件均保留。', 'Archived; existing conversations and files are retained.') }}</p><form v-if="instructionsOpen" class="workspace-inline-form" @submit.prevent="save({ instructions }, 'instructions')"><label>{{ tr('工作区说明', 'Workspace instructions') }}<textarea v-model="instructions" rows="4" :placeholder="tr('告诉智能体此工作区的目标、约定和输出要求。', 'Tell the agent this workspace’s goals, conventions, and output requirements.')" /></label><div><button class="primary">{{ tr('保存', 'Save') }}</button><button type="button" @click="instructionsOpen = false">{{ tr('取消', 'Cancel') }}</button></div></form><form v-if="resourcesOpen" class="workspace-inline-form" @submit.prevent="save({ resources }, 'resources')"><WorkspaceResourcePicker v-model="resources" :workspace-id="row.workspace_id" :language="language" /><p class="muted">{{ tr('更改会应用于后续轮次，现有会话和文件保留。', 'Changes apply to future turns. Existing conversations and files are retained.') }}</p><div><button class="primary">{{ tr('保存', 'Save') }}</button><button type="button" @click="resourcesOpen = false">{{ tr('取消', 'Cancel') }}</button></div></form><form v-if="editing" class="workspace-inline-form" @submit.prevent="save({ name: name.trim() }, 'edit')"><label>{{ tr('工作区名称', 'Workspace name') }}<input v-model="name" required maxlength="100" autofocus></label><div><button class="primary" :disabled="!name.trim()">{{ tr('保存', 'Save') }}</button><button type="button" @click="editing = false">{{ tr('取消', 'Cancel') }}</button></div></form><form v-if="moving" class="workspace-inline-form" @submit.prevent="migrate"><p class="muted">{{ row.follows_root ? tr('跟随根目录', 'Follows root directory') : tr('自定义位置', 'Custom location') }}</p><label>{{ tr('新存储目录', 'New storage directory') }}<input v-model="destination" required :placeholder="tr('输入一个尚不存在的目标目录', 'Enter a destination directory that does not exist')" autofocus></label><p class="muted">{{ tr('复制并验证后再切换，工作区 ID 和会话绑定保持不变，旧目录保留为备份。', 'Switch after copying and verification. Workspace ID and conversation links stay unchanged; the old directory is kept as a backup.') }}</p><div><button class="primary" :disabled="!destination.trim()">{{ tr('开始迁移', 'Start migration') }}</button><button type="button" @click="moving = false">{{ tr('取消', 'Cancel') }}</button></div></form><p v-if="row.error" class="error" role="alert">{{ row.error }}</p><SystemWorkspaceSnapshot v-if="row.kind === 'system'" :language="language" /></div></article></template>
